import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.DaGSOal_.js";const v=JSON.parse('{"title":"V","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/v.md","filePath":"glossaire-a-z/v.md"}'),n={name:"glossaire-a-z/v.md"};function i(s,e,l,d,u,p){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h1><h2 id="validator-fr-validateur" tabindex="-1">Validator (fr : Validateur) <a class="header-anchor" href="#validator-fr-validateur" aria-label="Permalink to &quot;Validator (fr : Validateur)&quot;">​</a></h2><p>Un participant qui vérifie les transactions et produit des blocs dans un système de preuve d’enjeu (<em>Proof of Stake</em>). Sur Cardano, les validateurs sont représentés par des pools de staking sélectionnés par le protocole de consensus Ouroboros.</p><h2 id="van-rossem" tabindex="-1">Van Rossem <a class="header-anchor" href="#van-rossem" aria-label="Permalink to &quot;Van Rossem&quot;">​</a></h2><p>Le hard fork de l’ère Conway du 18 juillet 2026, correspondant à la version 11 du protocole, qui a ajouté de nouvelles fonctionnalités Plutus et constitué la première mise à niveau de Cardano ratifiée entièrement par la gouvernance sur chaîne.</p><h2 id="vasil-vasil-hard-fork" tabindex="-1">Vasil (Vasil Hard Fork) <a class="header-anchor" href="#vasil-vasil-hard-fork" aria-label="Permalink to &quot;Vasil (Vasil Hard Fork)&quot;">​</a></h2><p>Le hard fork du 22 septembre 2022 qui a amélioré l’efficacité des contrats intelligents et les performances du réseau. Cette mise à niveau a notamment introduit les entrées de référence (<em>reference inputs</em>) et les données intégrées (<em>inline datums</em>).</p><h2 id="voltaire" tabindex="-1">Voltaire <a class="header-anchor" href="#voltaire" aria-label="Permalink to &quot;Voltaire&quot;">​</a></h2><p>La cinquième phase de la feuille de route initiale de Cardano, axée sur la gouvernance et l’autonomie financière du réseau. Ses concepts sont désormais mis en œuvre dans l’ère Conway, notamment grâce à la gouvernance sur chaîne et aux mécanismes de trésorerie.</p><h2 id="voting-power-fr-pouvoir-de-vote" tabindex="-1">Voting Power (fr : Pouvoir de vote) <a class="header-anchor" href="#voting-power-fr-pouvoir-de-vote" aria-label="Permalink to &quot;Voting Power (fr : Pouvoir de vote)&quot;">​</a></h2><p>Le poids dont dispose un participant dans les décisions de gouvernance de Cardano. Les détenteurs d’ada peuvent déléguer leur pouvoir de vote à un représentant délégué (<em>DRep</em>), qui vote sur les actions de gouvernance en leur nom. Pour les DReps et les opérateurs de pools de staking (<em>SPOs</em>), le poids des votes dépend de la quantité de mise active associée à leur vote, selon les règles de gouvernance applicables.</p><p>→ <a href="https://cardano.org/glossary/drep/" target="_blank" rel="noreferrer">Cardano.org — DRep</a></p><p>→ <a href="https://docs.cardano.org/about-cardano/governance-overview" target="_blank" rel="noreferrer">Documentation Cardano — Vue d’ensemble de la gouvernance</a></p><h2 id="voting-thresholds-fr-seuils-de-vote" tabindex="-1">Voting Thresholds (fr : Seuils de vote) <a class="header-anchor" href="#voting-thresholds-fr-seuils-de-vote" aria-label="Permalink to &quot;Voting Thresholds (fr : Seuils de vote)&quot;">​</a></h2><p>L’ensemble des paramètres du protocole qui définissent le pourcentage de votes requis auprès des différents organes de gouvernance — notamment les DReps et les opérateurs de pools de staking — pour ratifier chaque type d’action de gouvernance.</p><p>→ <a href="https://cardano.org/glossary/voting-thresholds/" target="_blank" rel="noreferrer">Cardano.org — Voting Thresholds</a></p><h2 id="vrf-verifiable-random-function-fr-fonction-aleatoire-verifiable" tabindex="-1">VRF (Verifiable Random Function) (fr : Fonction aléatoire vérifiable) <a class="header-anchor" href="#vrf-verifiable-random-function-fr-fonction-aleatoire-verifiable" aria-label="Permalink to &quot;VRF (Verifiable Random Function) (fr : Fonction aléatoire vérifiable)&quot;">​</a></h2><p>Un outil cryptographique qui produit une sortie aléatoire accompagnée d’une preuve permettant de vérifier sa validité. Sur Cardano, les opérateurs de pools de staking utilisent les VRF dans le protocole Ouroboros pour déterminer de manière imprévisible et vérifiable s’ils sont sélectionnés pour produire un bloc.</p>',18)])])}const f=a(n,[["render",i]]);export{v as __pageData,f as default};
